Here is the problem description:
<problem_description>
A string a of length m is called antipalindromic iff m is even, and for each i (1 ≤ i ≤ m) ai ≠ am - i + 1.Ivan has a string s consisting of n lowercase Latin letters; n is even. He wants to form some string t that will be an antipalindromic permutation of s. Also Ivan has denoted the beauty of index i as bi, and the beauty of t as the sum of bi among all indices i such that si = ti.Help Ivan to determine maximum possible beauty of t he can get.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    static int n;
    static char[] chars;
    static int[] vals;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        sc.nextLine();
        String s = sc.nextLine().trim();
        chars = s.toCharArray();
        vals = IntStream.range(0, n).map(i -> sc.nextInt()).toArray();
        sc.nextLine();

        List<Char> wrongChars = new ArrayList<>();
        List<Char> chars1 = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            boolean wrong = false;
            if (chars[i] == chars[n - i - 1]) {
                if (vals[i] > vals[n - i - 1]) {
                    swap(i);
                }
                wrong = true;
            }
            Char chr = new Char(chars[i], vals[i], i);
            if (wrong) wrongChars.add(chr);
            chars1.add(chr);
        }
        chars1.sort(Comparator.comparing(c -> c.val));

        int diff = 0;
        if (!isAntiPalindrome(chars)) {
            if (wrongChars.size() == 1) {
                Char wrongChar = wrongChars.get(0);
                for (int i = 0; i < n/2; i++) {
                    Char chr = chars1.get(i);
                    if (chr.chr != wrongChar.chr && chars[n - chr.idx - 1] != wrongChar.chr) {
                        diff = wrongChar.val + chr.val;
                        break;
                    }
                }
            } else if (wrongChars.size() > 1) {
                Map<Character, Integer> map = wrongChars.stream().collect(Collectors.toMap(c -> c.chr, c -> 1, Integer::sum, TreeMap::new));
                Map.Entry<Character, Integer> max = map.entrySet().stream().max(Map.Entry.comparingByValue()).get();
                List<Char> append = new ArrayList<>();
                while (max.getValue() * 2 > wrongChars.size() + append.size()) {
                    Character maxChar = max.getKey();
                    for (int i = 0; i < n/2; i++) {
                        Char chr = chars1.get(i);
                        if (chr.chr != maxChar && chars[n - chr.idx - 1] != maxChar && !wrongChars.contains(chr)) {
                            append.add(chr);
                            break;
                        }
                    }
                }
                diff = wrongChars.stream().mapToInt(c -> c.val).sum() + append.stream().mapToInt(c -> c.val).sum();
            }
        }

        int sum = Arrays.stream(vals).sum();
        System.out.println(sum - diff);
    }

    private static void swap(int i) {
        char tmp = chars[i];
        chars[i] = chars[n - i - 1];
        chars[n - i - 1] = tmp;
        int tmpVal = vals[i];
        vals[i] = vals[n - i - 1];
        vals[n - i - 1] = tmpVal;
    }

    private static boolean isAntiPalindrome(char[] chars) {
        for (int i = 0; i < chars.length/2; i++) {
            if (chars[i] == chars[chars.length - i - 1]) {
                return false;
            }
        }
        return true;
    }

    static class Char {
        char chr;
        int val;
        int idx;

        Char(char chr, int val, int idx) {
            this.chr = chr;
            this.val = val;
            this.idx = idx;
        }
    }
}
